use serde_json::{Value, from_str};
use std::cmp::Ordering;

pub fn solve(input: Value) -> Value {
    let mut pairs: Vec<(i64, i64)> = input.as_array()
        .unwrap()
        .iter()
        .map(|v| {
            let pair: Vec<i64> = v.as_array()
                .unwrap()
                .iter()
                .map(|n| n.as_i64().unwrap())
                .collect();
            (pair[0], pair[1])
        })
        .collect();

    pairs.sort_unstable_by(|a, b| {
        match a.0.cmp(&b.0) {
            Ordering::Equal => a.1.cmp(&b.1),
            other => other,
        }
    });

    Value::Array(pairs.into_iter().map(|(k, v)| Value::Array(vec![Value::Number(k.into()), Value::Number(v.into())])).collect())
}
